  // Not to be used by end users
  FeederSessionImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  FeederSessionImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_FeederSession,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_FeederSession,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_FeederSessionPtr,
  );

  void cancelFeed({required int feed}) => RustLib.instance.api
      .crateApiSessionFeederSessionCancelFeed(that: this, feed: feed);

  void close() =>
      RustLib.instance.api.crateApiSessionFeederSessionClose(that: this);

  /// Feed `portions` (1-48) once. The answer and the feed's end arrive
  /// as updates.
  void feed({required int portions}) => RustLib.instance.api
      .crateApiSessionFeederSessionFeed(that: this, portions: portions);

  /// Read the status again.
  void refresh() =>
      RustLib.instance.api.crateApiSessionFeederSessionRefresh(that: this);

  /// Connect and serve until the session ends: `updates` hears `Opened`,
  /// then the card, and `Closed` last. Runs once.
  Stream<SessionUpdate> run() =>
      RustLib.instance.api.crateApiSessionFeederSessionRun(that: this);
}

@sealed
class RecoveryImpl extends RustOpaque implements Recovery {
  // Not to be used by end users
  RecoveryImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  RecoveryImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_Recovery,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_Recovery,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_RecoveryPtr,
  );

  /// Hang up now: the feeder's window stays open for the next try rather
  /// than held by a screen that went away.
  void close() => RustLib.instance.api.crateApiSetupRecoveryClose(that: this);

  Uint8List code() =>
      RustLib.instance.api.crateApiSetupRecoveryCode(that: this);

  /// Run the exchange with the feeder at `address` (`ip` or `ip:port`),
  /// whose recovery window is open, reporting each reply. Runs once.
  /// Errors arrive on the stream: Dart holds only the stream, not this
  /// call's own result.
  Stream<SetupStep> run({required String address}) => RustLib.instance.api
      .crateApiSetupRecoveryRun(that: this, address: address);
}

